#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    int M = 3;
    vector<int> A(M), B(M);
    for (int i = 0; i < M; i++) cin >> A[i];
    for (int i = 0; i < M; i++) cin >> B[i];

    int initial_total = 0;
    for (int i = 0; i < M; i++) {
        initial_total += min(A[i], B[(i + 1) % M]);
    }

    // Implementation of Dinic's algorithm for max flow
    struct Edge {
        int to, rev;
        long long cap;
    };

    int size = 2 * M + 2;
    int s = 2 * M;
    int t = 2 * M + 1;
    vector<vector<Edge>> graph(size);

    auto add_edge = [&](int u, int v, long long cap) {
        graph[u].push_back({v, (int)graph[v].size(), cap});
        graph[v].push_back({u, (int)graph[u].size() - 1, 0});
    };

    for (int i = 0; i < M; i++) {
        add_edge(s, i, N);
        add_edge(M + i, t, B[i]);
        add_edge(i, M + i, A[i]);
        add_edge(i, M + ((i - 1 + M) % M), A[i]);
    }

    long long max_flow = 0;
    while (true) {
        vector<int> level(size, -1);
        level[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : graph[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        if (level[t] < 0) break;

        vector<int> iter(size, 0);
        function<long long(int, int, long long)> send_flow = [&](int v, int t, long long f) {
            if (v == t) return f;
            for (int &i = iter[v]; i < (int)graph[v].size(); i++) {
                auto &e = graph[v][i];
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long long pushed = send_flow(e.to, t, std::min(f, e.cap));
                    if (pushed > 0) {
                        e.cap -= pushed;
                        graph[e.to][e.rev].cap += pushed;
                        return pushed;
                    }
                }
            }
            return (long long)0;
        };

        long long flow;
        while ((flow = send_flow(s, t, LLONG_MAX)) > 0) {
            max_flow += flow;
        }
    }

    long long answer = N - max_flow;
    cout << answer << " " << initial_total << "\n";

    return 0;
}
